def phrase_manifest() -> dict[str, dict]:
    path = AUDIO / "manifest.json"
    payload = json.loads(path.read_text(encoding="utf-8"))
    rows = payload["recordings"]
    by_phrase = {row["phrase"]: row for row in rows}
    next_id = max(int(row["id"][3:]) for row in rows) + 1
    for lesson in LESSONS:
        for phrase, *_ in lesson["phrases"]:
            row = by_phrase.get(phrase)
            if row is None:
                row = {"id": f"kz-{next_id:03d}", "phrase": phrase,
                       "file": f"kz-{next_id:03d}.wav", "status": "candidate_review", "lessons": []}
                rows.append(row)
                by_phrase[phrase] = row
                next_id += 1
            for lang in LANGS:
                suffix = "" if lang == "ru" else f"-{lang}"
                name = f"{lesson['stem']}{suffix}.md"
                if name not in row["lessons"]:
                    row["lessons"].append(name)
            row["lessons"].sort()
    path.write_text(json.dumps(payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return by_phrase


def map_svg(lesson: dict, lang: str) -> str:
    idx = LANGS.index(lang)
    title = html.escape(lesson["title"][idx])
    titles = {"ru": "ЖИВАЯ ОПОРА", "kz": "ТІРЕК КАРТА", "en": "SPEAKING MAP"}
    footer = {"ru": "ЗАМЕТЬ → СКАЖИ → ВЫСЛУШАЙ → ПРОВЕРЬ", "kz": "БАЙҚА → АЙТ → ТЫҢДА → ТЕКСЕР", "en": "NOTICE → SAY → LISTEN → CHECK"}
    labels = [part.strip() for part in lesson["support"]]
    label_index = {"ru": 1, "kz": 0, "en": 2}[lang]
    labels = [item.split(" / ")[label_index] for item in labels]
    cards = []
    colors = ("#196b88", "#be6b36", "#655ab0", "#258573")
    examples_by_lesson = {
        49: (1, 2, 4, 5), 50: (1, 2, 3, 5), 51: (0, 1, 2, 4),
        52: (0, 4, 1, 2), 53: (5, 0, 1, 4), 54: (0, 1, 2, 4),
        55: (0, 1, 2, 4), 56: (0, 2, 3, 5),
    }
    number = int(lesson["stem"][:2])

    def lines(text: str, width: int, max_lines: int) -> list[str]:
        result = textwrap.wrap(text, width, break_long_words=False, break_on_hyphens=False)
        if len(result) > max_lines:
            result = result[:max_lines - 1] + [" ".join(result[max_lines - 1:])]
        return result

    for n, label in enumerate(labels):
        if number == 53:
            x, y, w, h = ((86, 375, 360, 205), (620, 265, 360, 205),
                          (620, 535, 360, 205), (1154, 375, 360, 205))[n]
        else:
            x, y, w, h = 73 + 373 * n, 304, 340, 300
        label_lines = lines(label, 19, 2)
        example = lesson["phrases"][examples_by_lesson[number][n]][0]
        example_lines = lines(example, 34 if number == 53 else 28, 2 if number == 53 else 3)
        label_markup = "".join(f'<text x="{x+w/2}" y="{y+100+j*34}" text-anchor="middle" font-size="25" font-weight="700" fill="#17364e">{html.escape(line)}</text>' for j, line in enumerate(label_lines))
        example_markup = "".join(f'<text x="{x+w/2}" y="{y+(155 if number == 53 else 166)+j*26}" text-anchor="middle" font-size="{18 if number == 53 else 20}" fill="#426073">{html.escape(line)}</text>' for j, line in enumerate(example_lines))
        cards.append(f'<g filter="url(#shadow)"><rect x="{x}" y="{y}" width="{w}" height="{h}" rx="22" fill="#fff" stroke="{colors[n]}" stroke-width="4"/><rect x="{x}" y="{y}" width="{w}" height="52" rx="22" fill="{colors[n]}"/><text x="{x+24}" y="{y+35}" font-size="25" fill="#fff" font-weight="700">0{n+1}</text>{label_markup}{example_markup}</g>')
    if number == 53:
        connectors = '<path d="M446 440H520V365H608"/><path d="M446 505H520V635H608"/><path d="M980 365H1050V440H1142"/><path d="M980 635H1050V505H1142"/>'
    elif number == 51:
        connectors = ""
    else:
        connectors = ''.join(f'<path d="M{73+373*n+345} 453h21"/>' for n in range(3))
    cards.append(f'<g fill="none" stroke="#29556b" stroke-width="5" stroke-linecap="round" stroke-linejoin="round" marker-end="url(#arrow)">{connectors}</g>')
    title_lines = textwrap.wrap(lesson["title"][idx], 46, break_long_words=False)
    title_markup = "".join(f'<text x="82" y="{177+j*54}" fill="#17364e" font-size="39" font-weight="800" font-family="DejaVu Sans,Arial,sans-serif">{html.escape(line)}</text>' for j, line in enumerate(title_lines))
    footer_y = 780 if number == 53 else 682
    footer_h = 58 if number == 53 else 86
    footer_text_y = 817 if number == 53 else 736
    return f'''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1600 900" role="img" aria-label="{title}"><defs><pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#d1e4ed" stroke-width="1"/></pattern><filter id="shadow" x="-20%" y="-25%" width="145%" height="160%"><feDropShadow dx="0" dy="12" stdDeviation="14" flood-color="#17364e" flood-opacity=".18"/></filter><marker id="arrow" markerWidth="9" markerHeight="9" refX="8" refY="4.5" orient="auto"><path d="M0 0L9 4.5L0 9Z" fill="#29556b"/></marker></defs><rect width="1600" height="900" fill="#edf7f7"/><rect width="1600" height="900" fill="url(#grid)"/><rect x="48" y="48" width="1504" height="804" rx="28" fill="#f9fcfc" stroke="#bfd5dd" stroke-width="3" filter="url(#shadow)"/><text x="82" y="117" fill="#ba433c" font-size="26" font-weight="800" font-family="DejaVu Sans,Arial,sans-serif">{titles[lang]} · {lesson['stem'][:2]}</text>{title_markup}<g font-family="DejaVu Sans,Arial,sans-serif">{''.join(cards)}</g><rect x="260" y="{footer_y}" width="1080" height="{footer_h}" rx="20" fill="#17364e" filter="url(#shadow)"/><text x="800" y="{footer_text_y}" text-anchor="middle" fill="#fff" font-size="27" font-weight="700" font-family="DejaVu Sans,Arial,sans-serif">{footer[lang]}</text></svg>'''


def render(lesson: dict, lang: str, next_lesson: dict | None, audio: dict[str, dict]) -> str:
    i = LANGS.index(lang)
    ui = UI[lang]
    c = COMMON[lang]
    parts = [f"# {lesson['title'][i]}", "", f"_Lead (summary):_ **{lesson['lead'][i]}**", "",
             f"## {ui[0]}", "", c["map"], "",
             f"![{lesson['title'][i]}](/static/course/kazakh-language/map-{lesson['map']}-{lang}.svg)", "",
             f"## {ui[1]}", "", lesson["scene"][i], "", f"## {ui[2]}", ""]
    for phrase, ru, kz, en in lesson["phrases"]:
        meaning = (ru, kz, en)[i]
        recording = audio[phrase]["file"]
        parts.extend((f"[{ui[16]}: {phrase}](/static/course/kazakh-language/audio/{recording}) — {meaning}", ""))
    sections = [(ui[3], c["listen"]), (ui[4], lesson["model"][i]),
                (ui[5], "```kazakh\n" + " → ".join(x.split(" / ")[0] for x in lesson["support"]) + "\n```"),
                (ui[6], lesson["limit"][i]), (ui[7], c["predict"]),
                (ui[8], c["recall"]), (ui[9], lesson["error"][i]),
                (ui[10], lesson["transfer"][i]), (ui[11], lesson["project"][i]),
                (ui[12], lesson["task"][i])]
    for heading, body in sections:
        parts.extend((f"## {heading}", "", body, ""))
    parts.extend((f"## {ui[13]}", ""))
    parts.extend("- " + value for value in c["repeat"])
    if next_lesson:
        parts.extend(("", f"[{ui[14]}: {next_lesson['title'][i]}](/read/kazakh-language-{next_lesson['stem']}?lang={lang})"))
    else:
        parts.extend(("", f"[{ui[15]}](/course/kazakh-language?lang={lang})"))
    return "\n".join(parts) + "\n"


def main() -> None:
    if len(LESSONS) != 8 or [int(x["stem"][:2]) for x in LESSONS] != list(range(49, 57)):
        raise ValueError("expected eight consecutive lessons 49–56")
    OUT.mkdir(parents=True, exist_ok=True)
    audio = phrase_manifest()
    for index, lesson in enumerate(LESSONS):
        upcoming = LESSONS[index + 1] if index + 1 < len(LESSONS) else None
        for lang in LANGS:
            suffix = "" if lang == "ru" else f"-{lang}"
            (OUT / f"{lesson['stem']}{suffix}.md").write_text(render(lesson, lang, upcoming, audio), encoding="utf-8")
            (MAPS / f"map-{lesson['map']}-{lang}.svg").write_text(map_svg(lesson, lang), encoding="utf-8")
    print(f"Prepared {len(LESSONS)*3} review lessons and maps; audio candidates are not approved")


if __name__ == "__main__":
    main()
